package org.apache.commons.math4.legacy.stat.descriptive;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class SummaryStatistics_ESTest_test12 extends SummaryStatistics_ESTest_scaffolding {

    /**
     * Verifies that toString() on a freshly created (empty) SummaryStatistics
     * reports a count of zero and NaN for every statistic, since no values
     * have been added yet.
     */
    @Test(timeout = 4000)
    public void testToStringOnEmptyStatisticsReportsZeroCountAndNaN() throws Throwable {
        SummaryStatistics emptyStatistics = new SummaryStatistics();

        String summary = emptyStatistics.toString();

        String expectedSummary =
                "SummaryStatistics:\n"
                + "n: 0\n"
                + "min: NaN\n"
                + "max: NaN\n"
                + "sum: NaN\n"
                + "mean: NaN\n"
                + "variance: NaN\n"
                + "standard deviation: NaN\n";
        assertEquals(expectedSummary, summary);
    }
}
